    File d = new File(dir);
    if (d.isDirectory()) {
        String[] children = d.list();
        for (int i = 0; i < children.length; i++) {
            File child = new File(d, children[i]);
            if (child.isFile() && child.getName().endsWith(".jar")) {
                try {
                    cpV.add(child.toURI().toURL());
                } catch (MalformedURLException e) {
                    e.printStackTrace();
                }
            }
        }
    }
}

