    StringBuilder buf = new StringBuilder(1024);
    FormatConverter fc = new FormatConverter(event);
    for (int i = 0; i < fc.length(); i++) {
        char c = fc.charAt(i);
        switch (c) {
            case 'd':
                buf.append(fc.getDate());
                break;
            case 'm':
                buf.append(fc.getMessage());
                break;
            case 'p':
                buf.append(fc.getPriority());
                break;
            case 't':
                buf.append(fc.getThread());
                break;
            case 'l':
                buf.append(fc.getLevel());
                break;
            case 'n':
                buf.append(fc.getThrowable());
                break;
            case 'a':
                buf.append(fc.arrayToString(fc.getArguments()));
                break;
            case 'o':
                buf.append(fc.objectToString(fc.getArgument()));
                break;
            case 'x':
                buf.append(fc.toString(fc.getArgument(), fc.getArgumentStyle()));
                break;
            default:
                buf.append(c);
                break;
        }
    }
    return buf.toString();
}

