public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }
    ParameterizedType parameterizedType = (ParameterizedType) genericType;
    Type[] typeArguments = parameterizedType.getActualTypeArguments();
    if (typeArguments.length == 0) {
        return null;
    }
    Class<?>[] resolvedTypes = new Class<?>[typeArguments.length];
    for (int i = 0; i < typeArguments.length; i++) {
        Type typeArgument = typeArguments[i];
        if (typeArgument instanceof Class<?>) {
            resolvedTypes[i] = (Class<?>) typeArgument;
        } else if (typeArgument instanceof ParameterizedType) {
            ParameterizedType argumentType = (ParameterizedType) typeArgument;
            if (argumentType.getRawType() instanceof Class<?>) {
                resolvedTypes[i] = (Class<?>) argumentType.getRawType();
            } else {
                return null;
            }
        } else if (typeArgument instanceof TypeVariable<?>) {
            TypeVariable<?> typeVariable = (TypeVariable<?>) typeArgument;
            Class<?> resolvedType = resolveParameterizedType(typeVariable, targetType);
            if (resolvedType == null) {
                return null;
            }
            resolvedTypes[i] = resolvedType;
        } else {
            return null;
        }
    }
    return resolvedTypes;
}

public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (genericType instanceof ParameterizedType) {
        ParameterizedType parameterizedType = (ParameterizedType) genericType;
        Type[] typeArguments = parameterizedType.getActualTypeArguments();
        Class<?>[] result = new Class<?>[typeArguments.length];
        for (int i = 0; i < typeArguments.length; i++) {
            Type typeArgument = typeArguments[i];
            if (typeArgument instanceof Class) {
                result[i] = (Class<?>) typeArgument;
            } else if (typeArgument instanceof ParameterizedType) {
                result[i] = (Class<?>) ((ParameterizedType) typeArgument).getRawType();
            } else if (typeArgument instanceof GenericArrayType) {
                Type componentType = ((GenericArrayType) typeArgument).getGenericComponentType();
                if (componentType instanceof Class) {
                    result[i] = Array.newInstance((Class<?>) componentType, 0).getClass();
                } else {
                    result[i] = null;
                }
            } else {
                result[i] = null;
            }
        }
        return result;
    } else {
        return null;
    }
}

