public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    // Reverse-engineer the type parameter mappings by created a Map of type parameters to actual types
    Map<TypeVariable<?>, Type> typeVarMap = new HashMap<>();
    Type currentType = targetType;
    while (currentType != null && currentType != Object.class) {
        if (currentType instanceof Class) {
            Class currentClass = (Class) currentType;
            TypeVariable<? extends Class>[] typeParams = currentClass.getTypeParameters();
            Type[] actualTypes = currentClass.getGenericSuperclass().getActualTypeArguments();
            for (int i = 0; i < typeParams.length; i++) {
                typeVarMap.put(typeParams[i], actualTypes[i]);
            }
        } else if (currentType instanceof ParameterizedType) {
            ParameterizedType paramType = (ParameterizedType) currentType;
            Class rawType = (Class) paramType.getRawType();
            Type[] actualTypes = paramType.getActualTypeArguments();
            TypeVariable<? extends Class>[] typeParams = rawType.getTypeParameters();
            for (int i = 0; i < typeParams.length; i++) {
                typeVarMap.put(typeParams[i], actualTypes[i]);
            }
        }
        currentType = currentType.getSuperclass();
    }

    // Resolve the type arguments for the genericType using the type parameter mappings
    if (genericType instanceof ParameterizedType) {
        ParameterizedType paramType = (ParameterizedType) genericType;
        Type[] actualTypes = paramType.getActualTypeArguments();
        Class<?>[] resolvedTypes = new Class[actualTypes.length];
        for (int i = 0; i < actualTypes.length; i++) {
            Type resolvedType = actualTypes[i];
            while (resolvedType instanceof TypeVariable) {
                TypeVariable typeVar = (TypeVariable) resolvedType;
                resolvedType = typeVarMap.get(typeVar);
            }
            resolvedTypes[i] = (Class<?>) resolvedType;
        }
        return resolvedTypes;
    }

    // If the genericType is not parameterized, return null
    return null;
}

public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (genericType instanceof ParameterizedType) {
        ParameterizedType parameterizedType = (ParameterizedType) genericType;
        Type[] typeArguments = parameterizedType.getActualTypeArguments();
        Class<?>[] arguments = new Class<?>[typeArguments.length];
        for (int i = 0; i < typeArguments.length; i++) {
            arguments[i] = getClassFromType(typeArguments[i], targetType);
        }
        return arguments;
    } else {
        return null;
    }
}

