long compressTimeBucket(long timeBucket, int dayStep) {
  // convert timeBucket to a Calendar instance
  Calendar calendar = Calendar.getInstance();
  calendar.setTimeInMillis(timeBucket);

  // calculate newDayStep as the nearest multiple of dayStep
  int newDayStep = (calendar.get(Calendar.DAY_OF_MONTH) / dayStep) * dayStep;

  // calculate the new time bucket in milliseconds based on the newDayStep
  long newTimeBucket = timeBucket + newDayStep;

  return newTimeBucket;
}

