public static long compressTimeBucket(long timeBucket, int dayStep) {
    // Step 1: Calculate the day difference between the time bucket and the closest dayStep day
    long dayDiff = timeBucket % dayStep;
    if (dayDiff == 0) {
      return timeBucket;
    }

    // Step 2: Calculate the number of days to add to the time bucket to reach the closest dayStep day
    int daysToAdd = dayStep - dayDiff;

    // Step 3: Add the calculated number of days to the time bucket
    return timeBucket + daysToAdd;
  }

