public void readFrom(final InputStream in) throws IOException {
    if (in == null) {
        throw new IOException("Null input stream");
    }

    int read = 0;
    while (read < capacity) {
        int bytesRead = in.read(buffer, read, capacity - read);
        if (bytesRead == -1) {
            break;
        }
        read += bytesRead;
    }

    if (read < capacity) {
        throw new IOException("Reached end of stream before filling buffer");
    }

    resetRead();
}

