	}

	if (value instanceof Character) {
		return value;
	} else if (value instanceof Number) {
		return Character.valueOf((char) ((Number) value).intValue());
	} else if (value instanceof String) {
		String stringValue = (String) value;
		if (stringValue.length() != 1) {
			throw new IllegalArgumentException("Cannot convert string of length " + stringValue.length() + " to Character");
		}
		return stringValue.charAt(0);
	} else {
		throw new IllegalArgumentException("Cannot convert " + value.getClass().getName() + " to Character");
	}
}

