public static int nextPrime(int desiredCapacity) {
  // Check if the desired capacity is already a prime number
  if (desiredCapacity <= 1) {
    return 2;
  }

  // Find the next prime number greater than or equal to the desired capacity
  for (int i = desiredCapacity + 1; i < Integer.MAX_VALUE; i++) {
    if (isPrime(i)) {
      return i;
    }
  }

  // If no prime number was found, return the original desired capacity
  return desiredCapacity;
}

