public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < str.length(); i++) {
        char ch = str.charAt(i);
        if (ch == '\\') {
            if (i == str.length() - 1) {
                throw new Exception("invalid escape sequence at the end of the string");
            }
            char nextCh = str.charAt(i + 1);
            switch (nextCh) {
            case 'n':
                sb.append('\n');
                break;
            case 't':
                sb.append('\t');
                break;
            case 'b':
                sb.append('\b');
                break;
            case 'r':
                sb.append('\r');
                break;
            case 'f':
                sb.append('\f');
                break;
            case 's':
                sb.append(' ');
                break;
            case '\'':
                sb.append('\'');
                break;
            case '\"':
                sb.append('\"');
                break;
            case '\\':
                sb.append('\\');
                break;
            case 'u':
                if (i >= str.length() - 5) {
                    throw new Exception("invalid Unicode escape sequence at the end of the string");
                }
                String hex = str.substring(i + 2, i + 6);
                try {
                    sb.append((char) Integer.parseInt(hex, 16));
                } catch (NumberFormatException e) {
                    throw new Exception("invalid Unicode escape sequence: \\u" + hex);
                }
                i += 4;
                break;
            case 'x':
                if (i >= str.length() - 3) {
                    throw new Exception("invalid hexadecimal escape sequence at the end of the string");
                }
                String hex = str.substring(i + 2, i + 4);
                try {
                    sb.append((char) Integer.parseInt(hex, 16));
                } catch (NumberFormatException e) {
                    throw new Exception("invalid hexadecimal escape sequence: \\x" + hex);
                }
                i += 3;
                break;
            default:
                throw new Exception("invalid escape sequence: \\" + nextCh);
            }
            i++;
        } else {
            sb.append(ch);
        }
    }
    return sb.toString();
}

