    if (array == null) {
        return Array.newInstance(newArrayComponentType, 1);
    }
    int newLength = Array.getLength(array) + 1;
    Object newArray = Array.newInstance(array.getClass().getComponentType(), newLength);
    System.arraycopy(array, 0, newArray, 0, newLength - 1);
    Array.set(newArray, newLength - 1, newArrayComponentType.cast(null));
