public final String readUtf(int constantPoolEntryIndex, char[] charBuffer) {
    if (constantPoolEntryIndex < 1 || constantPoolEntryIndex > classFile.constant_pool_count) {
        throw new IndexOutOfBoundsException("Invalid constant pool index: " + constantPoolEntryIndex);
    }
    ConstantPoolEntry entry = classFile.constant_pool[constantPoolEntryIndex];
    if (entry.tag != ConstantPoolEntry.CONSTANT_Utf8) {
        throw new IllegalArgumentException("Wrong constant pool entry type: expected CONSTANT_Utf8, got " + entry.tag);
    }
    int nameLength = entry.length - 2; // length does not include the length field itself
    if (charBuffer.length < nameLength) {
        throw new IllegalArgumentException("Buffer too small to hold Utf8 string");
    }
    return new String(charBuffer, 0, nameLength);
}

