private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    OuterFaceCirculator result = null;
    Set<Node> visited = new HashSet<>();
    Deque<Node> queue = new ArrayDeque<>();
    queue.offer(start);
    while (!queue.isEmpty()) {
        Node current = queue.poll();
        if (predicate.test(current)) {
            result = new OuterFaceCirculator(current);
            break;
        }
        if (!visited.contains(current)) {
            visited.add(current);
            for (Node neighbor : current.getNeighbors(dir)) {
                if (neighbor != stop && !visited.contains(neighbor)) {
                    queue.offer(neighbor);
                }
            }
        }
    }
    return result;
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    OuterFaceCirculator circulator = new OuterFaceCirculator(start, dir);
    while (!circulator.getNode().equals(stop)) {
        if (predicate.test(circulator.getNode())) {
            return circulator;
        }
        circulator.next();
    }
    return circulator;
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    OuterFaceCirculator circ = new OuterFaceCirculator(start, dir);
    while (!circ.node.equals(stop)) {
        if (predicate.test(circ.node)) {
            return circ;
        }
        circ.next();
    }
    return circ;
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    OuterFaceCirculator result = new OuterFaceCirculator(start, dir);
    while (result.node() != stop && !predicate.test(result.node())) {
        result.move(dir);
    }
    return result;
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    for (OuterFaceCirculator circ = new HalfEdge(start).circulate(dir); circ != stop; circ = new HalfEdge(circ.getNext()).circulate(dir)) {
        if (predicate.test(circ.getNode())) {
            return circ;
        }
    }
    return new HalfEdge(stop);
}

