public ByteVector putByteArray(byte[] byteArrayValue, int byteOffset, int byteLength) {
    if (byteArrayValue == null) {
        byteArrayValue = new byte[byteLength];
    }
    ensureCapacity(byteLength);
    System.arraycopy(byteArrayValue, byteOffset, data, length, byteLength);
    length += byteLength;
    return this;
}

public ByteVector putByteArray(final byte[] byteArrayValue,final int byteOffset,final int byteLength) {
    if (byteArrayValue == null) {
        return this;
    }
    if (byteOffset < 0 || byteOffset > byteArrayValue.length) {
        throw new IndexOutOfBoundsException("Invalid byteOffset: " + byteOffset);
    }
    if (byteLength < 0 || byteLength > byteArrayValue.length - byteOffset) {
        throw new IndexOutOfBoundsException("Invalid byteLength: " + byteLength);
    }
    int length = this.length;
    if (this.length + byteLength > this.data.length) {
        int newLength = Math.max(2 * this.data.length, this.length + byteLength);
        byte[] newData = new byte[newLength];
        System.arraycopy(this.data, 0, newData, 0, this.length);
        this.data = newData;
    }
    System.arraycopy(byteArrayValue, byteOffset, this.data, this.length, byteLength);
    this.length += byteLength;
    return this;
}

public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
    if (byteArrayValue != null) {
        int newLength = byteOffset + byteLength;
        if (newLength > byteArrayValue.length) {
            throw new IndexOutOfBoundsException("Invalid offset/length " + byteOffset + " / " + byteLength + " for byte array of length " + byteArrayValue.length);
        }
        ensureCapacity(newLength);
        System.arraycopy(byteArrayValue, byteOffset, data, length, byteLength);
        length += byteLength;
    }
    return this;
}

