private String unescapeId(String input) {
    String escaped = "";
    for (int i = 0; i < input.length(); i++) {
        char c = input.charAt(i);
        if (c == '\\') {
            if (i + 1 < input.length() && (input.charAt(i + 1) == 'u' || input.charAt(i + 1) == 'U')) {
                escaped += "\\u";
                i++;
            } else if (i + 1 < input.length() && (input.charAt(i + 1) == 'x' || input.charAt(i + 1) == 'X')) {
                escaped += "\\x";
                i++;
            } else {
                escaped += "\\";
            }
        } else {
            escaped += c;
        }
    }
    return escaped;
}

