public static Class<?> resolveBound(TypeVariable<?> typeVariable) {
    Type[] bounds = typeVariable.getBounds();
    if (bounds.length == 0) {
        return Object.class;
    }
    Type bound = bounds[0];
    if (bound instanceof Class) {
        return (Class<?>) bound;
    } else if (bound instanceof ParameterizedType) {
        return (Class<?>) ((ParameterizedType) bound).getRawType();
    } else if (bound instanceof WildcardType) {
        Type[] lowerBounds = ((WildcardType) bound).getLowerBounds();
        if (lowerBounds.length == 0) {
            return Object.class;
        }
        return (Class<?>) lowerBounds[0];
    }
    return Unknown.class;
}

