private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices){
  // check if the number of vertices is greater than 1
  if (vertices.size() <= 1){
    return false;
  }
  // check if the graph has more than one connected component
  if (graph.connectedSet(vertices).size() != 1){
    return false;
  }
  // check if all vertices have a degree of at least k-1
  for (V vertex : vertices){
    if (graph.inDegreeOf(vertex) < vertices.size() - 1 || graph.outDegreeOf(vertex) < vertices.size() - 1){
      return false;
    }
  }
  return true;
}

public static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {

    // Identify the induced subgraph between the vertices
    Subgraph<V, E> inducedSubgraph = graph.getInducedSubgraph(vertices);

    // Create a new set that contains vertex neighbors
    Set<V> neighbors = new HashSet<>();

    // Iterate through the vertices in the induced subgraph
    for (V vertex : inducedSubgraph.getVertices()) {
        // Add all vertex neighbors to the neighbor set
        neighbors.addAll(inducedSubgraph.getNeighbors(vertex));
    }

    // Check if the vertex neighbor set contains all vertices in the induced subgraph
    return neighbors.containsAll(inducedSubgraph.getVertices());
}

private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    for (V v1 : vertices) {
        for (V v2 : vertices) {
            if (v1 != v2 && !graph.containsEdge(v1, v2)) {
                return false;
            }
        }
    }
    return true;
}

private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    // Check if all vertices are connected to each other
    for (V v1 : vertices) {
        for (V v2 : vertices) {
            if (v1 != v2 && !graph.getEdgesBetween(v1, v2).isEmpty()) {
                // The graph is not completely connected, so it is not a clique
                return false;
            }
        }
    }
    // The graph is completely connected, so it is a clique
    return true;
}

