public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            // check if the line matches any of the time ranges
            boolean match = false;
            for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
                if (line.startsWith(timeRange.getStartTime() + " ") && line.endsWith(timeRange.getEndTime() + " ") {
                    match = true;
                    break;
                }
            }
            if (!match) {
                continue;
            }
    // parse the thread snapshot and add to the list
            String[] columns = line.split(",");
            int tid = Integer.parseInt(columns[0].trim());
            String name = columns[1].trim();
            long timestamp = Long.parseLong(columns[2].trim());
            ThreadSnapshot snapshot = new ThreadSnapshot(tid, name, timestamp);
            threadSnapshots.add(snapshot);
        }
    }
    return threadSnapshots;
}

